<?php $e = static fn (mixed $v): string => App\Core\View::e($v); ?><section class="page-stack"><div class="section-heading"><div><p class="eyebrow">Governança de dados</p><h1>Retenção e arquivamento</h1><p class="muted">Configure prazos e registre cada arquivamento ou restauração. Partidas, súmulas, evidências e logs oficiais não podem ser apagados por esta tela.</p></div></div><?php if (!empty($message)): ?><p class="success" role="status"><?= $e($message) ?></p><?php endif; ?><div class="panel-grid"><?php foreach ($policies as $policy): ?><article class="panel"><h2><?= $e($policy['name']) ?></h2><form method="post" action="<?= $e(App\Core\Config::url('/admin/retencao/' . $policy['scope_key'])) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><label>Prazo em dias (vazio = sem expiração)<input type="number" min="1" max="36500" name="retention_days" value="<?= $e($policy['retention_days'] ?? '') ?>"></label><label class="check"><input type="checkbox" name="allow_archive" value="1" <?= !empty($policy['allow_archive']) ? 'checked' : '' ?>> Permitir arquivamento</label><label class="check"><input type="checkbox" name="allow_restore" value="1" <?= !empty($policy['allow_restore']) ? 'checked' : '' ?>> Permitir restauração</label><label class="check"><input type="checkbox" name="allow_soft_delete" value="1" <?= !empty($policy['allow_soft_delete']) ? 'checked' : '' ?>> Permitir exclusão lógica</label><p class="muted"><?= !empty($policy['protected']) ? 'Classe protegida: exclusão permanente bloqueada.' : 'Exclusão permanente continua indisponível por padrão.' ?></p><button type="submit">Salvar política</button></form></article><?php endforeach; ?></div><article class="panel"><h2>Histórico de ações</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Registro</th><th>Ação</th><th>Motivo</th><th>Usuário</th></tr></thead><tbody><?php foreach ($actions as $action): ?><tr><td><?= $e($action['created_at']) ?></td><td><?= $e($action['entity_type']) ?> #<?= (int) $action['entity_id'] ?></td><td><?= $e($action['action']) ?></td><td><?= $e($action['reason']) ?></td><td><?= $e($action['user_name']) ?></td></tr><?php endforeach; ?></tbody></table></div></article></section>
